independent-practice.solution:
def initials(full_name):
    out = ""
    for part in full_name.split():
        if out:
            out = out + "."
        out = out + part[0].upper()
    return out

def is_palindrome(text):
    cleaned = text.replace(" ", "").lower()
    return cleaned == cleaned[::-1]

def field(line, n):
    parts = line.split(",")
    if n < 0 or n >= len(parts):
        return ""
    return parts[n].strip()

def title_line(heading):
    out = ""
    for word in heading.split():
        if out:
            out = out + " "
        out = out + word[:1].upper() + word[1:].lower()
    return out

def describe(word):
    if word == "":
        return "empty"
    return f"{word} has {len(word)} letters, from {word[0]} to {word[-1]}"

exam.solution:
def initial_and_surname(full_name):
    parts = full_name.split()
    if not parts:
        return ""
    if len(parts) == 1:
        return parts[0][:1].upper() + parts[0][1:]
    last = parts[-1]
    return f"{parts[0][0].upper()}. {last[:1].upper()}{last[1:]}"
